"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7499],{47499:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-pce-avgust-stavka-frs","locale":"ru","title":"Инфляция в США в августе оказалась ниже прогноза, но часть замедления дал пересчёт статистики","description":"Инфляция в США в августе 3,4% при прогнозе 3,7%. Ставку ФРС не снижает, рынок лишь меньше ждёт повышения в октябре: шанс 35%. Почему часть замедления дал пересчёт статистики.","blocks":[{"id":"b001","kind":"paragraph","text":"Министерство торговли США 30 сентября 2026 года опубликовало данные об инфляции за август. Цены выросли на 3,4% за год, хотя ждали 3,7%. Без еды и энергии, цены на которые сильно скачут, рост составил 3% при прогнозе 3,3%. Этот показатель называется PCE, на него в первую очередь смотрит Федеральная резервная система США, американский центробанк. Её цель 2%."},{"id":"b002","kind":"paragraph","text":"Цифра сразу изменила ожидания рынка. В сентябре ФРС подняла ставку впервые с 2023 года, до 3,75–4%. После новых данных шанс ещё одного повышения на заседании 27–28 октября упал примерно с 45% до 35%. Это не поворот к дешёвым деньгам: снижать ставку ФРС не собирается и не обещает. Рынок просто меньше уверен, что её поднимут ещё раз."},{"id":"b003","kind":"paragraph","text":"Но замедление без еды и энергии нарисовала статистика. Бюро экономического анализа США изменило расчёт цен на юридические услуги, программы и управление инвестициями и пересчитало по новой методике данные с 2021 года. Это похоже на магазин, который сменил весы и пересчитал старые чеки: \xabподешевело\xbb, хотя покупатель платит столько же. Такой пересмотр задним числом называют ревизией. Ревизия снизила июльскую инфляцию без еды и энергии на 0,36 пункта, примерно с 3,3% до 3%. Значит, в августе она не упала, а осталась на месте."},{"id":"b004","kind":"paragraph","text":"Экономика США при этом не тормозит. Рост ВВП во втором квартале 2026 года пересмотрели с 1,5% до 2,2%, расходы людей в августе росли быстрее всего за год. Президент Федерального резервного банка Миннеаполиса Нил Кашкари сказал, что инфляция около 3% \xabвсё ещё слишком высокая\xbb и держится выше цели больше 5 лет. Свежие данные, по его словам, эту картину почти не изменили."},{"id":"b005","kind":"paragraph","text":"Поэтому кредиты в США не подешевели. Доходность 10-летних облигаций правительства США выросла примерно до 5,3%, а от неё считают ипотеку. Для России новость работает через доллар, и он держится: облигации США платят больше 5%, деньги в долларах остаются дорогими. Официальный курс на 1 октября 83,56 рубля за доллар, на 87 копеек ниже, чем днём раньше. Рубль укрепился по внутренним причинам: в конце квартала экспортёры продавали валютную выручку, а импортёры притихли перед недельными праздниками в Китае."},{"id":"b006","kind":"paragraph","text":"Чего пока не знаем: данные за август не учитывают сентябрьский рост цен на топливо из-за войны с Ираном, и следующий отчёт может вернуть разговор о повышении ставки. Для тех, кто держит доллары, выбор такой. Продавать их на новости о замедлении инфляции значит верить цифре, которую во многом сделал пересчёт. Покупать в расчёте на новые повышения ставки значит ставить на отчёт, которого ещё никто не видел."},{"id":"b007","kind":"heading","text":"Какая инфляция в США в августе 2026 года?"},{"id":"b008","kind":"paragraph","text":"3,4% за год по индексу PCE, главному ориентиру ФРС, при прогнозе 3,7%. Без еды и энергии 3% при прогнозе 3,3%. Цель ФРС 2%."},{"id":"b009","kind":"heading","text":"Повысит ли ФРС ставку в октябре 2026 года?"},{"id":"b010","kind":"paragraph","text":"После данных за август рынок оценивает шанс примерно в 35% против 45% накануне. Сейчас ставка ФРС 3,75–4%, решение примут 27–28 октября."},{"id":"b011","kind":"heading","text":"Почему инфляция в США оказалась ниже прогноза?"},{"id":"b012","kind":"paragraph","text":"Отчасти из-за смены методики. Статистики пересчитали цены на юридические услуги, программы и управление инвестициями начиная с 2021 года. Июльская инфляция без еды и энергии после пересчёта снизилась на 0,36 пункта, примерно с 3,3% до 3%."}],"sources":[{"label":"Fed\'s preferred gauge showed core inflation at 3.0% in August","url":"https://www.cnbc.com/2026/09/30/feds-preferred-gauge-showed-core-inflation-at-3point0percent-in-august-much-lighter-than-expected.html"},{"label":"Minneapolis Fed President Neel Kashkari interview","url":"https://www.cnbc.com/2026/09/30/watch-minneapolis-fed-president-neel-kashkari.html"},{"label":"Good news in US inflation report boosts chances Fed won\'t hike rates","url":"https://www.theguardian.com/business/2026/sep/30/inflation-report-interest-rates-fed"},{"label":"PCE inflation eases to 3.4%, cooling the case for another Fed rate hike","url":"https://finance.yahoo.com/economy/policy/article/pce-inflation-eases-to-34--cooling-the-case-for-another-fed-rate-hike-125513195.html"},{"label":"PCE price index revised down","url":"https://finance.yahoo.com/economy/articles/pce-price-index-revised-down-123741659.html"},{"label":"Fed\'s preferred inflation metric came in cooler","url":"https://finance.yahoo.com/economy/articles/feds-preferred-inflation-metric-came-163426036.html"},{"label":"Fed\'s preferred inflation gauge declined","url":"https://finance.yahoo.com/economy/policy/articles/feds-preferred-inflation-gauge-declined-174601544.html"},{"label":"Fed preferred measure of inflation rose 3.4%","url":"https://finance.yahoo.com/economy/policy/articles/fed-preferred-measure-inflation-rose-124249351.html"},{"label":"Gold steady after softer inflation data","url":"https://finance.yahoo.com/markets/commodities/articles/gold-steady-softer-inflation-data-000816044.html"},{"label":"Fed\'s Kashkari says inflation goes beyond oil prices","url":"https://finance.yahoo.com/economy/policy/articles/feds-kashkari-says-inflation-goes-150738609.html"},{"label":"Официальный курс доллара опустился ниже 84 рублей","url":"https://www.vedomosti.ru/finance/news/2026/09/30/1233185-kurs-opustilsya"},{"label":"Курс доллара, евро и юаня на 1 октября 2026 года: почему рубль резко укрепился","url":"https://www.vbr.ru/novosti/kursy-valyut/2026/09/30/kurs-valut-na-1-oktyabrya/"},{"label":"Meeting calendars and information","url":"https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm"}],"sourceBodySha256":"1145a94c8144e6d38a235e40e919942738f6348f62bad69c60f81ff17dc4c1a0"}')}}]);